{
  "tasks": [
    {
      "task_id": "T01",
      "title": "各团队响应分钟中位数及升序排列",
      "business_question": "按团队计算响应分钟的中位数，并按中位数升序排列。注意：不要推断团队绩效。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心业务目标（按团队计算响应分钟中位数），且无法执行排序约束。这是唯一满足所有核心需求C01, C02, C03的任务。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0002",
                "alias": "response_median"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "response_median",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
